// Explicit virtual RF presentation: no guessed distance or hidden automatic pairing.
export const RFID_CARD={name:'RFID beyaz kart · 1K',category:'Girişler',detail:'13.56 MHz · UID + programlanabilir blok 4',width:180,height:114,scale:1,asset:'expansion-rfidCard.svg',pins:[],pinDefs:[]};
export const CARD_PRESETS=[{name:'Personel',uid:0x04a10001,data:'PERSONEL-001'},{name:'Ziyaretçi',uid:0x04b20002,data:'ZIYARETCI-002'},{name:'Servis',uid:0x04c30003,data:'SERVIS-003'}];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const uidText=n=>(n>>>0).toString(16).toUpperCase().padStart(8,'0').match(/../g).join(' ');
export function rfidEnvironment(project,component){const p=component?.params||{};if(!['mfrc522','pn532'].includes(component?.type)||!p.cardId)return p;const card=project.components.find(c=>c.id===p.cardId&&c.type==='rfidCard');return card?{...p,uid:card.params.uid??CARD_PRESETS[0].uid,present:card.params.present??1,initialData:card.params.data??CARD_PRESETS[0].data}:{...p,present:0};}
export function cardMarkup(c){const p=c.params,on=!!(p.present??1);return `<rect x="1" y="1" width="178" height="112" rx="10" fill="#000" opacity=".22" transform="translate(2 3)"/><rect x="1" y="1" width="178" height="112" rx="10" fill="#fafaf7" stroke="#7b8d9a" stroke-width="2"/><path d="M15 25h48m-48 6h30" stroke="#e1e5e5" stroke-width="3"/><path d="M136 22q12 12 0 24m7-29q17 17 0 34m7-40q23 23 0 46" fill="none" stroke="#7b9199" stroke-width="2.4"/><text x="15" y="60" fill="#1b3544" font-size="11" font-family="Consolas,monospace">${uidText(p.uid??CARD_PRESETS[0].uid)}</text><text x="15" y="79" fill="#425963" font-size="9" font-family="Consolas,monospace">${escape(p.data??CARD_PRESETS[0].data)}</text><text x="15" y="99" fill="#617a84" font-size="8">MIFARE 1K · sanal kart</text><g data-rfid-present="${c.id}" role="button" tabindex="0" aria-label="${c.id} kartı ${on?'uzaklaştır':'sun'}" aria-pressed="${on}" style="cursor:pointer"><rect x="123" y="86" width="44" height="18" rx="5" fill="${on?'#157653':'#445763'}"/><text x="145" y="98" text-anchor="middle" fill="#fff" font-size="8" pointer-events="none">${on?'SUNULDU':'UZAKTA'}</text></g>`;}
export function rfidInspector(c,project={components:[]}){if(c.type==='rfidCard')return `<div class="property"><label for="rfid-preset">Hazır program</label><select id="rfid-preset"><option value="">Özel</option>${CARD_PRESETS.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}</select></div><div class="property"><label for="rfid-uid">UID (8 hex)</label><input id="rfid-uid" maxlength="8" value="${(c.params.uid??CARD_PRESETS[0].uid).toString(16).toUpperCase().padStart(8,'0')}"></div><div class="property"><label for="rfid-data">Blok 4 (16 ASCII)</label><input id="rfid-data" maxlength="16" value="${escape(c.params.data??CARD_PRESETS[0].data)}"></div><p class="inspector-note">Okuyucuyu seçip bu kartı eşleştirin. Veriyi düzenlemek blok 4'ü yeniden programlar; firmware yazmaları MCU resetinde korunur. Sanal UID seçimi gerçek kart UID yazma desteği anlamına gelmez.</p>`;if(!['mfrc522','pn532'].includes(c.type))return '';return `<div class="property"><label for="rfid-card">Sunulan kart</label><select id="rfid-card"><option value="">Dahili sanal kart</option>${project.components.filter(x=>x.type==='rfidCard').map(x=>`<option value="${x.id}" ${c.params.cardId===x.id?'selected':''}>${x.id} · ${uidText(x.params.uid??CARD_PRESETS[0].uid)}</option>`).join('')}</select></div><p class="inspector-note">Beyaz kartı seçin; kartın SUNULDU/UZAKTA düğmesi RF varlığını değiştirir. Dahili kart seçiliyken eski UID/kart alanları kullanılır.</p>`;}
export function bindRFIDInspector(c,edit,toast){const node=id=>document.getElementById(id);if(node('rfid-card'))node('rfid-card').onchange=e=>edit(()=>c.params.cardId=e.target.value);if(node('rfid-preset'))node('rfid-preset').onchange=e=>{if(e.target.value==='')return;const p=CARD_PRESETS[+e.target.value];edit(()=>Object.assign(c.params,{uid:p.uid,data:p.data,present:1}));};if(node('rfid-uid'))node('rfid-uid').onchange=e=>{if(!/^[\da-f]{8}$/i.test(e.target.value)){toast('UID: 8 hexadecimal karakter.');e.target.value=(c.params.uid??CARD_PRESETS[0].uid).toString(16).padStart(8,'0');return;}edit(()=>c.params.uid=parseInt(e.target.value,16));};if(node('rfid-data'))node('rfid-data').onchange=e=>{if(!/^[\x20-\x7e]{0,16}$/.test(e.target.value)){toast('Blok 4: en fazla 16 ASCII karakter.');e.target.value=c.params.data??CARD_PRESETS[0].data;return;}edit(()=>c.params.data=e.target.value);};}
